  data.profiles = Object.fromEntries(data.modalities.map(m => [m, unit([0, 1].map(j => data.history.reduce((s, h) => s + h[m][j], 0) / data.history.length))]));
  data.candidates.forEach(item => {
    item.scores = data.modalities.map(m => dot(data.profiles[m], item[m]));
    item.late = dot(data.weights, item.scores);
    item.early = data.modalities.flatMap((m, j) => item[m].map(x => Math.sqrt(data.weights[j]) * x));
  });
  data.earlyProfile = data.modalities.flatMap((m, j) => data.profiles[m].map(x => Math.sqrt(data.weights[j]) * x));
  data.ranking = [...data.candidates].sort((a, b) => b.late - a.late || a.id.localeCompare(b.id)).map(x => x.id);
  data.attention.scaled = data.attention.keys.map(k => dot(data.attention.query, k) / Math.sqrt(data.attention.dk));
  data.attention.weights = softmax(data.attention.scaled);
  data.attention.output = [0, 1].map(j => data.attention.values.reduce((s, v, i) => s + data.attention.weights[i] * v[j], 0));
  data.gate = { logits: [Math.log(4), Math.log(2), 0, 0], weights: softmax([Math.log(4), Math.log(2), 0, 0]) };
  const last = data.candidates[2];
  data.missing = { id: last.id, missing: 'V', mask: [1, 1, 1, 0], numerator: dot(data.weights.slice(0, 3), last.scores.slice(0, 3)), availableWeight: .8 };
